def kth_smallest_divisor(n, k):
    # Calculate the number of divisors of n
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            # If divisors are equal, count only once
            if i == n // i:
                count += 1
            else:
                count += 2

    # Check if there are at least k divisors
    if count < k:
        return -1

    # Collect all divisors
    divisors = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)

    # Sort the divisors to get the k-th smallest
    divisors.sort()

    return divisors[k - 1]

