def find_kth_divisor(n, k):
    def count_divisors(limit):
        return sum(1 for i in range(1, int(limit**0.5) + 1) if n % i == 0)

    if count_divisors(n) < k:
        return -1

    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        if count_divisors(mid) >= k:
            high = mid - 1
        else:
            low = mid + 1
    return low

